from dataclasses import dataclass
from typing import Union

@dataclass
class Quit: pass

@dataclass
class Move:
    x: int
    y: int

@dataclass
class Write:
    text: str

Message = Union[Quit, Move, Write]

def process(msg: Message):
    match msg:
        case Quit():
            print("Quit")
        case Move(x, y):
            print(f"Move to ({x}, {y})")
        case Write(text):
            print(f"Write: {text}")

